public abstract class Shape
{
    private Shape() { }                              // no external derivation
    public sealed class Circle : Shape { public double R { get; init; } }
    public sealed class Rect   : Shape { public double W { get; init; } public double H { get; init; } }
}

static double Area(Shape s) => s switch
{
    Shape.Circle c => Math.PI * c.R * c.R,
    Shape.Rect r   => r.W * r.H,
    _ => throw new UnreachableException(),           // needed until C# 15 closed
};

